import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { Search, ChevronDown, CheckCircle, Video, Trash2 } from 'lucide-react';
import { useLanguage } from '@/components/LanguageContext';

export default function DemonlistPage() {
  const { t } = useLanguage();
  const [levels, setLevels] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentUser, setCurrentUser] = useState<any>(null);

  const [search, setSearch] = useState('');
  const [tab, setTab] = useState<'ALL' | 'MAIN' | 'EXTENDED' | 'LEGACY'>('ALL');
  const [mode, setMode] = useState<'CLASSIC' | 'PLATFORMER'>('CLASSIC');

  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 15;

  useEffect(() => {
    const userStr = localStorage.getItem('gdvnc_user');
    if (userStr) {
      try {
        setCurrentUser(JSON.parse(userStr));
      } catch (e) {}
    }
  }, []);

  const fetchLevels = () => {
    setLoading(true);
    fetch(`/api/demons?mode=${mode}`)
      .then(res => res.json())
      .then(data => {
        if (data.success) {
          setLevels(data.levels || []);
        }
        setLoading(false);
      })
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    fetchLevels();
  }, [mode]);

  const handleDeleteLevel = async (e: React.MouseEvent, id: string, name: string) => {
    e.preventDefault();
    if (!currentUser || currentUser.role !== 'ADMIN') return;

    if (confirm(`Bạn có chắc chắn muốn XÓA VĨNH VIỄN màn chơi "${name}" và toàn bộ kỷ lục của nó không?`)) {
      try {
        const res = await fetch(`/api/admin/levels?id=${id}`, {
          method: 'DELETE',
        });
        const data = await res.json();
        if (data.success) {
          alert(`Đã xóa thành công màn chơi "${name}"!`);
          fetchLevels();
        } else {
          alert(`Lỗi: ${data.error}`);
        }
      } catch (error) {
        alert('Lỗi kết nối khi xóa màn chơi.');
      }
    }
  };

  const getThumbnail = (lvl: any) => {
    if (lvl.youtubeId) return `https://img.youtube.com/vi/${lvl.youtubeId}/hqdefault.jpg`;
    return 'https://raw.githubusercontent.com/GDColon/GDBrowser/master/assets/difficulties/demon-extreme-featured.png'; // Fallback
  };

  const filtered = levels.filter(lvl => {
    if (tab === 'MAIN') {
      if (!lvl.placement || lvl.placement > 75) return false;
    } else if (tab === 'EXTENDED') {
      if (!lvl.placement || lvl.placement <= 75 || lvl.placement > 150) return false;
    } else if (tab === 'LEGACY') {
      if (!lvl.placement || lvl.placement <= 150) return false;
    }

    if (!search) return true;
    return (
      lvl.name.toLowerCase().includes(search.toLowerCase()) ||
      lvl.creatorName?.toLowerCase().includes(search.toLowerCase())
    );
  });

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const paginatedData = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  return (
    <div className="space-y-6 pb-24">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b" style={{ borderColor: 'var(--border-ui)' }}>
        <div className="space-y-1">
          <h1 className="text-xl font-black tracking-tight flex items-center gap-2 ui-title">
            {t('demonlist.title')}
          </h1>
          <p className="text-xs ui-dim max-w-md">{t('demonlist.desc')}</p>
        </div>
        <div className="flex bg-black/10 dark:bg-white/10 p-1 rounded-xl">
          <button 
            onClick={() => { setMode('CLASSIC'); setCurrentPage(1); }}
            className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-colors ${mode === 'CLASSIC' ? 'bg-white dark:bg-black shadow-sm text-white' : 'opacity-60 hover:opacity-100'}`}
          >	
            Classic
          </button>
          <button 
            onClick={() => { setMode('PLATFORMER'); setCurrentPage(1); }}
            className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-colors ${mode === 'PLATFORMER' ? 'bg-white dark:bg-black shadow-sm text-white' : 'opacity-60 hover:opacity-100'}`}
          >
            Platformer
          </button>
        </div>
      </div>

      {/* Controls */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 ui-dim" />
          <input 
            type="text" 
            placeholder={t('demonlist.search_demon')}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-9 pr-4 py-2.5 rounded-xl text-xs font-semibold ui-input focus:ring-2 focus:ring-red-500/20"
          />
        </div>
        <div className="flex items-center gap-2">
          {['ALL', 'MAIN', 'EXTENDED', 'LEGACY'].map((tName) => (
            <button
              key={tName}
              onClick={() => { setTab(tName as any); setCurrentPage(1); }}
              className={`px-3 py-2 rounded-xl text-xs font-bold transition-all ${tab === tName ? 'shadow-sm text-white' : 'hover:bg-black/5 dark:hover:bg-white/5 ui-dim'}`}
              style={{ backgroundColor: tab === tName ? 'var(--accent)' : 'transparent' }}
            >
              {t(`demonlist.${tName.toLowerCase()}` as any)}
            </button>
          ))}
        </div>
      </div>

      {/* Level List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {loading ? (
          <div className="col-span-full p-12 text-center ui-dim text-xs font-medium">{t('demonlist.loading')}</div>
        ) : paginatedData.length === 0 ? (
          <div className="col-span-full p-12 text-center ui-dim text-xs font-medium">{t('demonlist.empty')}</div>
        ) : (
          paginatedData.map((lvl, idx) => {
            const placement = lvl.placement || '-';
            return (
              <Link href={`/demons/${lvl.id}`} key={lvl.id} className="group relative rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-all border ui-card flex flex-col h-48">
                {/* Background Image */}
                <div 
                  className="absolute inset-0 bg-cover bg-center transition-transform duration-500 group-hover:scale-105"
                  style={{ backgroundImage: `url(${getThumbnail(lvl)})`, filter: 'brightness(0.6)' }}
                />

                {/* Overlay Gradient */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent" />

                {/* Content */}
                <div className="relative p-4 flex flex-col h-full justify-between text-white">
                  <div className="flex justify-between items-start">
                    <span className="px-2.5 py-1 rounded-lg text-xs font-black bg-black/50 backdrop-blur-sm border border-white/10">
                      #{placement}
                    </span>
                    <div className="flex gap-2">
                      {currentUser?.role === 'ADMIN' && (
                        <button
                          onClick={(e) => handleDeleteLevel(e, lvl.id, lvl.name)}
                          className="px-2.5 py-1 rounded-lg text-[11px] font-bold bg-red-500/80 hover:bg-red-500 backdrop-blur-sm border border-white/10 text-white transition-colors"
                          title="Delete Level"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      )}
                      <span className="text-xs font-bold flex items-center gap-1 opacity-80 bg-black/50 backdrop-blur-sm px-2.5 py-1 rounded-lg border border-white/10">
                        <CheckCircle className="w-3.5 h-3.5" />
                        {lvl.records?.length || 0}
                      </span>
                    </div>
                  </div>

                  <div>
                    <h2 className="text-xl font-black drop-shadow-lg truncate">{lvl.name}</h2>

